"""Summarize wf tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import errno
import json
import os
from pathlib import Path
import re


EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def read_table(node, table):
    path = node / "wf" / (table + ".json")
    try:
        flags = getattr(os, "O_NOATIME", 0)
        try:
            fd = os.open(path, os.O_RDONLY | flags)
        except PermissionError as exc:
            # A readable file owned by another user can reject O_NOATIME.
            if not flags or exc.errno != errno.EPERM:
                raise
            fd = os.open(path, os.O_RDONLY)
        with os.fdopen(fd, "r", encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or any(not isinstance(col, str) for col in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp if stamp.tzinfo is not None else stamp.replace(tzinfo=now.tzinfo)


def routine(row, now):
    every = row["every"]
    if EVERY.fullmatch(every) is None:
        raise ValueError("invalid every")
    last = timestamp(row["last_time"], now) if row["last_time"] else None
    code_text = row["last_code"]
    if code_text not in ("", "running") and CODE.fullmatch(code_text) is None:
        raise ValueError("invalid last_code")
    code = None if code_text == "" else ("running" if code_text == "running" else int(code_text))
    next_at = None
    if last is not None and every[-1] != "r":
        due = last + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
        next_at = due.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_at is not None and now >= due:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": every,
            "last_time": row["last_time"] or None, "last_code": code,
            "state": state, "next": next_at}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else ("due" if at <= now else "pending")
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": {key: 0 for key in
                         ("running", "never", "failed", "overdue", "ok")},
                         "schedule": {key: 0 for key in
                         ("interrupted", "due", "pending")}}, "bad": []}
    for table in ("routines", "schedule"):
        rows, errors = read_table(node, table)
        result["bad"].extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    result["bad"].append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            if (not isinstance(row, dict)
                    or any(not isinstance(value, str) for value in row.values())
                    or any(key not in row for key in REQUIRED[table])
                    or not isinstance(name, str) or not name):
                result["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            try:
                item = routine(row, now) if table == "routines" else scheduled(row, now)
            except (ValueError, OverflowError):
                result["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            result[table].append(item)
            result["counts"][table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    result["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only wf runs summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True, separators=(",", ":")))
    return 0
